const cfg = $('Settings').first().json;
const body = $input.first().json;
const models = Array.isArray(body.models) ? body.models : [];
const now = Date.now();
const assumedMs = Number(cfg.assumedKeepAliveMinutes) * 60 * 1000;
const idleMs = Number(cfg.idleMinutes) * 60 * 1000;
const dayMs = 24 * 60 * 60 * 1000;
const dryRun = cfg.dryRun !== false;
const unloadPinned = cfg.unloadPinned === true;
const state = $getWorkflowStaticData('global');
const previous = (state.lastAction && typeof state.lastAction === 'object') ? state.lastAction : {};
const next = {};
function parseTime(value) {
  if (typeof value === 'number' && isFinite(value)) {
    if (value < 1e12) return value * 1000;
    return value;
  }
  return Date.parse(String(value == null ? '' : value));
}
function row(action, modelName, line) {
  const key = modelName || '(none)';
  const changed = previous[key] !== action;
  if (action !== 'gone') next[key] = action;
  return { json: { action: action, model: modelName, changed: changed, dryRun: dryRun, ollamaUrl: cfg.ollamaUrl, logPath: cfg.logPath, logLine: new Date(now).toISOString() + ' ' + line + '\n' } };
}
const out = [];
if (models.length === 0) {
  out.push(row('none-loaded', '', 'no loaded models'));
}
for (let i = 0; i < models.length; i++) {
  const model = models[i] || {};
  const name = String(model.name || model.model || '');
  const expires = parseTime(model.expires_at);
  if (!isFinite(expires)) { out.push(row('keep', name, 'skip ' + name + ' missing expiry')); continue; }
  const pinned = (expires - now) > dayMs;
  if (pinned && !unloadPinned) { out.push(row('pinned-skip', name, 'pinned skip ' + name)); continue; }
  const idleFor = now - (expires - assumedMs);
  if (idleFor >= idleMs) {
    if (dryRun) out.push(row('would-unload', name, 'would unload ' + name));
    else out.push(row('unload', name, 'unload ' + name));
  } else {
    out.push(row('keep', name, 'keep ' + name));
  }
}
Object.keys(previous).forEach(function (key) {
  if (key !== '(none)' && !Object.prototype.hasOwnProperty.call(next, key)) {
    const r = row('gone', key, 'no longer loaded ' + key);
    r.json.changed = true;
    out.push(r);
  }
});
state.lastAction = next;
return out;

const line = String($json.logLine == null ? '' : $json.logLine);
const b64 = Buffer.from(line, 'utf8').toString('base64');
return {
  json: {
    action: $json.action,
    changed: $json.changed,
    model: $json.model,
    ollamaUrl: $json.ollamaUrl,
    logPath: $json.logPath,
    logLine: line
  },
  binary: { data: { data: b64, mimeType: 'text/plain', fileName: 'gpu-guard.log', fileExtension: 'log' } }
};
